/*
 * A190808  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 2x and 3x+1 are in a.
 * https://oeis.org/A190808
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 26, u16 n <= 2877, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A190808
   Definition: a(1)=1; if x∈A, then 2x and 3x+1 are also in A.
   The function returns the n‑th smallest member (n≥1). */

#include <stddef.h>

/* Use static arrays of fixed size – large enough for n ≤ 10000 */
#define MAX_CACHE 20000
#define MAX_HEAP  20000

static seq_t seq_cache[MAX_CACHE];
static size_t seq_size = 0;                   /* number of stored terms */

static seq_t heap[MAX_HEAP];
static size_t heap_size = 0;                 /* current heap size */

/* ---- Min‑heap helpers ------------------------------------------ */

static void heap_push(seq_t val)
{
    if (heap_size >= MAX_HEAP) return;          /* safety, should not happen */
    size_t i = heap_size++;
    heap[i] = val;

    /* bubble up */
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap[parent] <= heap[i]) break;
        seq_t tmp = heap[parent]; heap[parent] = heap[i]; heap[i] = tmp;
        i = parent;
    }
}

static seq_t heap_pop(void)
{
    seq_t min = heap[0];
    --heap_size;
    if (heap_size > 0) {
        heap[0] = heap[heap_size];
        /* bubble down */
        size_t i = 0;
        for (;;) {
            size_t left = (i << 1) + 1;
            if (left >= heap_size) break;
            size_t right = left + 1;
            size_t smallest = left;
            if (right < heap_size && heap[right] < heap[left]) smallest = right;
            if (heap[i] <= heap[smallest]) break;
            seq_t tmp = heap[i]; heap[i] = heap[smallest]; heap[smallest] = tmp;
            i = smallest;
        }
    }
    return min;
}

/* ---- Sequence generator ------------------------------------------- */

seq_t a(idx_t n)
{
    if (n == 0) return 0;            /* undefined for offset 0 */

    /* Ensure cache holds at least n terms */
    while (seq_size < (size_t)n) {
        if (heap_size == 0 && seq_size == 0) {
            heap_push((seq_t)1);     /* seed the heap with the initial term */
        }

        seq_t val = heap_pop();

        /* Skip duplicates in the output sequence */
        if (seq_size == 0 || val != seq_cache[seq_size - 1]) {
            if (seq_size < MAX_CACHE) seq_cache[seq_size++] = val;
        }

        /* Generate the successors of the extracted value */
        heap_push(val * 2);
        heap_push(val * 3 + 1);
    }

    return seq_cache[n - 1];
}
